 {modal.type==='confirm'&&<div className="modal-form"><div className="notice warning"><AlertTriangle size={22}/><span>{modal.text}</span></div><FormError message={formError}/><div className="modal-footer"><button className="btn secondary" onClick={()=>setModal(null)}>Cancel</button><button className="btn primary" disabled={busy} onClick={modal.action}>{busy?'Saving…':modal.label}</button></div></div>}
