function PublishDialog({data,session,departmentId,semester,busy,error,onClose,onPublish,onSave}:{data:AcademicData;session:string;departmentId:string;semester:number;busy:boolean;error:string;onClose:()=>void;onPublish:()=>Promise<void>;onSave:()=>Promise<void>}){const check=publicationCheck(data,session,departmentId,semester);const dep=data.departments.find(d=>d.id===departmentId);return <div className="modal-form"><div className="publish-symbol"><GraduationCap size={40}/></div><div className="publish-context"><h3>{dep?.code} · {semesterName(semester)}</h3><span>Session {session}</span></div><div className="publish-stats"><div><b>{check.students.length}</b><span>Students</span></div><div><b>{check.courses.length}</b><span>Subjects</span></div><div><b>{check.pending}</b><span>Missing marks</span></div></div><div className="exam-completion">{check.exams.map(exam=>{const total=check.students.length*check.courses.length;const done=check.students.reduce((n,s)=>n+check.courses.filter(c=>{const value=scoreMap(data).get(scoreKey(s.id,c.id,exam.id));return value!==null&&value!==undefined;}).length,0);return <div key={exam.id}><span>{exam.name}</span><b className={done===total?'success-text':'warning-text'}>{done} / {total}{done===total&&<Check size={15}/>}</b></div>;})}</div><div className={'notice '+(check.ready?'success':'warning')}>{check.ready?<ShieldCheck size={20}/>:<AlertTriangle size={20}/>}<span>{check.ready?'All marks are complete. Students will see their semester results after publication.':`Complete ${check.pending} missing marks before publishing this semester.`}</span></div><FormError message={error}/><div className="modal-footer"><button className="btn secondary" onClick={onClose}>Cancel</button><button className="btn secondary" disabled={busy} onClick={onSave}><Save size={16}/> Save draft</button><button className="btn primary" disabled={busy||!check.ready} onClick={onPublish}><CheckCircle2 size={16}/>{busy?'Publishing…':'Publish results'}</button></div></div>;}
function StudentDetails({data,student:s}:{data:AcademicData;student:Student}){const items=[['Student name',s.name],['Father’s name',s.fatherName||'—'],['Mother’s name',s.motherName||'—'],['Registration number',s.registration],['Roll number',s.roll||'—'],['Department',data.departments.find(d=>d.id===s.departmentId)?.name||'—'],['Session',s.session],['Current semester',semesterName(s.semester)],['Date of birth',s.dateOfBirth||'—'],['Email',s.email||'—']];return <div className="student-details">{items.map(([label,value])=><div key={label}><span>{label}</span><b>{value}</b></div>)}</div>;}
function GradingScale({data,print=false}:{data:AcademicData;print?:boolean}){const bands=[...data.settings.bands].sort((a,b)=>b.min-a.min);if(print)return <section className="print-grading compact-scale"><h4>Grading system · 4.00 scale</h4><div className="print-band-grid"><div><b>Grade</b><span>Marks %</span><strong>Point</strong></div>{bands.map((b,i)=><div key={b.min}><b>{b.letter}</b><span>{b.min}–{i===0?'100':`<${bands[i-1].min}`}</span><strong>{b.point.toFixed(2)}</strong></div>)}</div></section>;return <section className={print?'print-grading':'panel grading-box'}><div className="section-heading"><h2>Grading system</h2><span className="badge violet">4.00 scale</span></div><table><thead><tr><th>Marks (%)</th><th>Grade</th><th>Point</th></tr></thead><tbody>{bands.map((b,i)=><tr key={b.min}><td>{b.min}–{i===0?'100':`<${bands[i-1].min}`}</td><td><span className={'grade-badge '+(b.point===0?'failed':'')}>{b.letter}</span></td><td>{b.point.toFixed(2)}</td></tr>)}</tbody></table></section>;}
function StudentPortal({data,student:s,view,onView}:{data:AcademicData;student:Student;view:number|'overall';onView:(s:number|'overall')=>void}){const cg=cumulative(data,s,true);const count=Array.from({length:s.semester},(_,i)=>i+1).filter(n=>data.published.includes(keyFor(s.session,s.departmentId,n))).length;const canPrint=view==='overall'?count>0:data.published.includes(keyFor(s.session,s.departmentId,view));return <><div className="student-hero"><div className="avatar big">{initials(s.name)}</div><div><span className="overline">{s.registration}</span><h2>{s.name}</h2><p>{data.departments.find(d=>d.id===s.departmentId)?.name} · {s.session}</p></div><div className="student-cgpa"><span>Overall CGPA</span><strong>{cg.cgpa.toFixed(2)}<small>/ 4.00</small></strong></div></div><div className="student-stat-row"><span><GraduationCap size={21}/><b>{cg.earned}</b> Credits earned</span><span><CheckCircle2 size={20}/><b>{count}</b> Published semesters</span><span><CalendarDays size={20}/>{semesterName(s.semester)}</span></div><div className="student-results-layout"><section className="panel result-panel"><div className="section-heading"><h2>{view==='overall'?'Overall marksheet':semesterName(view)+' result'}</h2><div className="inline"><select className="standalone-select" aria-label="View result semester" value={view} onChange={e=>onView(e.target.value==='overall'?'overall':Number(e.target.value))}><option value="overall">Overall result</option>{Array.from({length:s.semester},(_,i)=><option key={i} value={i+1}>{semesterName(i+1)}</option>)}</select><button className="btn primary" disabled={!canPrint} onClick={()=>window.print()}><Printer size={17}/> Print</button></div></div><Marksheet data={data} student={s} semester={view}/></section><GradingScale data={data}/></div></>;}
function Marksheet({data,student:s,semester,admin=false}:{data:AcademicData;student:Student;semester:number|'overall';admin?:boolean}){const department=data.departments.find(d=>d.id===s.departmentId);const all=semester==='overall';const result=all?null:semesterResult(data,s,semester);const published=all?data.published.some(k=>k.startsWith(s.session+'|'+s.departmentId+'|')):!!result?.published;const visible=admin||published;const cg=cumulative(data,s,!admin);const available=Array.from({length:s.semester},(_,i)=>i+1).filter(n=>admin||data.published.includes(keyFor(s.session,s.departmentId,n)));return <article className="marksheet"><header className="marksheet-header">{logo()}<div><h2>{data.settings.institution}</h2>{data.settings.address&&<p>{data.settings.address}</p>}<h3>{all?'Consolidated Academic Transcript':`${semesterName(semester)} Academic Marksheet`}</h3>{all&&<p>{available.length} of {s.semester} semesters included</p>}<span className={'marksheet-status '+(published?'published':'draft')}>{published?'Published result':'Draft · Not published'}</span></div></header><div className="marksheet-identity"><div><span>Student name</span><b>{s.name}</b></div><div><span>Registration number</span><b>{s.registration}</b></div><div><span>Father’s name</span><b>{s.fatherName||'—'}</b></div><div><span>Mother’s name</span><b>{s.motherName||'—'}</b></div><div><span>Department</span><b>{department?.name}</b></div><div><span>Session / Roll</span><b>{s.session} / {s.roll||'—'}</b></div>{s.dateOfBirth&&<div><span>Date of birth</span><b>{s.dateOfBirth}</b></div>}</div>
 {!visible?<div className="pending-result"><Clock size={39}/><h3>Result not published yet</h3><span>Your result will appear here after publication.</span></div>:all?<><div className="consolidated-results">{available.map(n=>{const r=semesterResult(data,s,n);return <section className="semester-section" key={n}><div className="semester-section-heading"><h4>{semesterName(n)}</h4><b>GPA: {r.complete?r.gpa.toFixed(2):'Pending'}{!r.published&&<small> Draft</small>}</b></div><div className="table-scroll"><table className="transcript-table consolidated"><thead><tr><th>Code</th><th>Course name</th><th>Credits</th><th>Marks (%)</th><th>Grade</th><th>Point</th></tr></thead><tbody>{r.results.map(x=><tr key={x.course.id}><td>{x.course.code}</td><td>{x.course.name}</td><td>{x.course.credits}</td><td>{x.complete?x.percentage.toFixed(2):'—'}</td><td><b>{x.grade.letter}</b></td><td>{x.complete?x.grade.point.toFixed(2):'—'}</td></tr>)}</tbody></table></div></section>;})}</div><div className="marksheet-summary"><div><span>Total attempted credits</span><b>{cg.credits}</b></div><div><span>Credits earned</span><b>{cg.earned}</b></div><div className="cgpa-result"><span>Overall CGPA</span><b>{cg.cgpa.toFixed(2)}<small> / 4.00</small></b></div></div>{!available.length&&<Empty title="No semester results have been published"/>}</>:<><div className="table-scroll"><table className="transcript-table"><thead><tr><th>Course</th><th>Credits</th>{planFor(data,s.session,s.departmentId,semester).map(e=><th key={e.id}>{e.name}<small>/{e.maxMarks}</small></th>)}<th>Total</th><th>Marks %</th><th>Grade</th><th>Point</th></tr></thead><tbody>{result!.results.map(r=><tr key={r.course.id}><td><b>{r.course.code}</b><small>{r.course.name}</small></td><td>{r.course.credits}</td>{r.values.map((v,i)=><td key={i}>{v===undefined||v===null?'—':round(v)}</td>)}<td>{r.complete?round(r.total):'—'}</td><td>{r.complete?r.percentage.toFixed(2):'—'}</td><td><span className={'grade-badge '+(r.grade.point===0?'failed':'')}>{r.grade.letter}</span></td><td>{r.complete?r.grade.point.toFixed(2):'—'}</td></tr>)}</tbody></table></div><div className="marksheet-summary"><div><span>Credits earned</span><b>{result!.earned}<small> / {result!.totalCredits}</small></b></div><div><span>Semester GPA</span><b>{result!.complete?result!.gpa.toFixed(2):'Pending'}<small> / 4.00</small></b></div><div className="cgpa-result"><span>Overall CGPA</span><b>{cg.cgpa.toFixed(2)}<small> / 4.00</small></b></div></div></>}
 {visible&&<><div className="marksheet-policy">GPA = Σ (course credits × grade points) ÷ Σ attempted credits. CGPA uses the latest completed attempt for each course code.{!admin&&' Only published results are included.'}</div><div className="print-only"><GradingScale data={data} print/></div><div className="marksheet-signatures"><div><span/>{data.settings.examOffice||'Examination Office'}</div><div><span/>Controller of Examinations</div></div></>}
 </article>;}
function SettingsEditor({data,busy,error,onSave}:{data:AcademicData;busy:boolean;error:string;onSave:(s:InstituteSettings)=>Promise<void>}){const [draft,setDraft]=useState<InstituteSettings>(()=>structuredClone(data.settings));useEffect(()=>setDraft(structuredClone(data.settings)),[data.settings]);return <form className="settings-form" onSubmit={e=>{e.preventDefault();onSave(draft);}}><section className="panel"><div className="section-heading"><h2>Institute information</h2></div><div className="settings-profile">{logo()}<div className="form-grid"><label className="span-two">Institute name<input required value={draft.institution} onChange={e=>setDraft({...draft,institution:e.target.value})}/></label><label className="span-two">Address<input value={draft.address} onChange={e=>setDraft({...draft,address:e.target.value})}/></label><label>Examination office<input value={draft.examOffice} onChange={e=>setDraft({...draft,examOffice:e.target.value})}/></label><label>Portal title<input value={draft.subtitle} onChange={e=>setDraft({...draft,subtitle:e.target.value})}/></label></div></div></section><section className="panel settings-grading"><div className="section-heading"><div><h2>Marks and grading system</h2><span>Grade boundaries are applied to the total marks percentage.</span></div><span className="badge violet">4.00 scale</span></div><div className="grading-editor">{draft.bands.map((b,i)=><div key={i}><label>Grade<input aria-label={'Grade label '+(i+1)} maxLength={4} required value={b.letter} onChange={e=>setDraft({...draft,bands:draft.bands.map((x,j)=>j===i?{...x,letter:e.target.value}:x)})}/></label><label>Minimum %<input aria-label={'Minimum marks '+b.letter} type="number" min={0} max={100} step={.5} required value={b.min} onChange={e=>setDraft({...draft,bands:draft.bands.map((x,j)=>j===i?{...x,min:Number(e.target.value)}:x)})}/></label><label>Grade point<input aria-label={'Grade point '+b.letter} type="number" min={0} max={4} step={.01} required value={b.point} onChange={e=>setDraft({...draft,bands:draft.bands.map((x,j)=>j===i?{...x,point:Number(e.target.value)}:x)})}/></label></div>)}</div></section><section className="panel default-exams"><div className="section-heading"><h2>Default examination plan</h2></div><div className="exam-checkboxes">{data.exams.map(e=><label className="checkbox-label" key={e.id}><input type="checkbox" checked={draft.defaultExamIds.includes(e.id)} onChange={ev=>setDraft({...draft,defaultExamIds:ev.target.checked?[...draft.defaultExamIds,e.id]:draft.defaultExamIds.filter(x=>x!==e.id)})}/>{e.name}<span>{e.maxMarks} marks</span></label>)}</div></section><FormError message={error}/><div className="settings-footer"><button type="button" className="btn secondary" onClick={()=>setDraft(structuredClone(data.settings))}>Discard changes</button><button className="btn primary" disabled={busy} type="submit"><Save size={18}/>{busy?'Saving…':'Save settings'}</button></div></form>;}
function parseCSV(text:string){const rows:string[][]=[];let row:string[]=[],value='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){value+='"';i++;}else quote=!quote;}else if(c===','&&!quote){row.push(value.trim());value='';}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value.trim());if(row.some(Boolean))rows.push(row);row=[];value='';}else value+=c;}if(quote)throw Error('Unclosed quoted field in CSV.');row.push(value.trim());if(row.some(Boolean))rows.push(row);return rows;}
function ImportSheet({data,students,courses,exam,locked,busy,error,onClose,onImport}:{data:AcademicData;students:Student[];courses:Course[];exam:Exam;locked:boolean;busy:boolean;error:string;onClose:()=>void;onImport:(s:Score[])=>Promise<void>}){const [scores,setScores]=useState<Score[]>([]),[localError,setLocalError]=useState(''),[filename,setFilename]=useState('');function template(){downloadCSV([['Registration','Student name',...courses.map(c=>c.code)],...students.map(s=>[s.registration,s.name,...courses.map(()=> '')])],exam.name.replace(/[^a-zA-Z0-9]+/g,'-')+'-Template.csv');}async function read(file?:File){setScores([]);setLocalError('');setFilename(file?.name||'');if(!file)return;try{if(file.size>2_000_000)throw Error('Choose a CSV smaller than 2 MB.');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));const expected=['Registration','Student name',...courses.map(c=>c.code)];if(rows[0]?.join('|')!==expected.join('|'))throw Error('The columns do not match this semester. Download and use the template.');if(rows.length<2)throw Error('The file has no student rows.');const seen=new Set<string>();const imported:Score[]=[];rows.slice(1).forEach((row,i)=>{if(row.length!==expected.length)throw Error(`Row ${i+2}: incorrect number of columns.`);const s=students.find(s=>s.registration.toLowerCase()===row[0].toLowerCase());if(!s)throw Error(`Row ${i+2}: registration ${row[0]} is not in this cohort.`);if(seen.has(s.id))throw Error(`Row ${i+2}: duplicate student.`);seen.add(s.id);courses.forEach((c,j)=>{const raw=row[j+2];const value=raw===''?null:Number(raw);if(value!==null&&(!Number.isFinite(value)||value<0||value>exam.maxMarks))throw Error(`Row ${i+2} · ${c.code}: marks must be 0–${exam.maxMarks}.`);imported.push({studentId:s.id,courseId:c.id,examId:exam.id,value});});});setScores(imported);}catch(e){setLocalError((e as Error).message);}}
 return <div className="modal-form"><div className="notice info"><Table2 size={20}/><span>{exam.name} · {students.length} students · {courses.length} subjects. Each row is one student.</span></div><button className="btn secondary" onClick={template}><Download size={16}/> Download CSV template</button><label className="upload-zone"><Upload size={30}/><b>{filename||'Choose a marks CSV'}</b><span>Maximum 2 MB</span><input aria-label="Upload marks CSV" type="file" accept=".csv,text/csv" disabled={locked} onChange={e=>read(e.target.files?.[0])}/></label>{scores.length>0&&<div className="notice success"><CheckCircle2 size={20}/><span>{scores.length} marks ready to import.</span></div>}{locked&&<div className="notice warning"><LockKeyhole size={19}/><span>Unpublish this semester before importing marks.</span></div>}<FormError message={localError||error}/><div className="modal-footer"><button className="btn secondary" onClick={onClose}>Cancel</button><button className="btn primary" disabled={busy||locked||!scores.length} onClick={()=>onImport(scores)}><Upload size={17}/>{busy?'Importing…':'Import marks'}</button></div></div>;}
