export function migrateData(value:unknown):AcademicData{
 if((value as AcademicData)?.version===2)return value as AcademicData;
 const old=(value||createLegacy()) as LegacyData;
 const names=Array.from(new Set([...old.students.map(s=>s.department),...old.courses.map(c=>c.department)]));
 const departments=names.map((name,i)=>({id:`d-${i}`,name,code:['CSE','EEE','BBA'][i]||name.split(/\s+/).map(v=>v[0]).join('').slice(0,7)}));
 const id=(name:string)=>departments.find(d=>d.name===name)!.id;
 const exams=[{id:'assignment',name:'Assignment',maxMarks:old.settings.assignment},{id:'classTest',name:'Class Test',maxMarks:old.settings.classTest},{id:'midterm',name:'Midterm Examination',maxMarks:old.settings.midterm},{id:'final',name:'Final Examination',maxMarks:old.settings.final}];
 const students=old.students.map((s,i)=>({id:s.id,registration:s.roll,roll:s.roll,name:s.name,fatherName:i===0?'Abdul Rahman':'',motherName:i===0?'Salma Begum':'',email:s.email,dateOfBirth:'',departmentId:id(s.department),session:s.session,semester:s.semester}));
 return {version:2,departments,students,courses:old.courses.map(c=>({id:c.id,code:c.code,name:c.name,departmentId:id(c.department),semester:c.semester,credits:c.credits})),exams,scores:old.marks.flatMap(m=>exams.map(e=>({studentId:m.studentId,courseId:m.courseId,examId:e.id,value:m[e.id as 'assignment'|'classTest'|'midterm'|'final']}))),plans:[],published:old.published.map(k=>{const [session,dept,sem]=k.split('|');return keyFor(session,id(dept),Number(sem));}),settings:{institution:DEFAULT_INSTITUTION,subtitle:'Academic Result Management System',address:'',examOffice:'Office of the Controller of Examinations',bands:old.settings.bands,defaultExamIds:exams.map(e=>e.id)},activities:old.activities.map(a=>({id:a.id,text:a.text,time:a.time}))};
}
export const createAcademicDemo=()=>migrateData(createLegacy());
const cache=new WeakMap<AcademicData,Map<string,number|null>>();
export function scoreMap(d:AcademicData){let m=cache.get(d);if(!m){m=new Map(d.scores.map(s=>[scoreKey(s.studentId,s.courseId,s.examId),s.value]));cache.set(d,m);}return m;}
export function planFor(d:AcademicData,session:string,departmentId:string,semester:number){const ids=d.plans.find(p=>p.key===keyFor(session,departmentId,semester))?.examIds||d.settings.defaultExamIds;return ids.map(id=>d.exams.find(e=>e.id===id)).filter((e):e is Exam=>!!e);}
export function gradeFor(percent:number,bands:Band[]){return [...bands].sort((a,b)=>b.min-a.min).find(b=>percent>=b.min)||{min:0,letter:'F',point:0};}
export function courseResult(d:AcademicData,s:Student,c:Course){const exams=planFor(d,s.session,s.departmentId,c.semester);const map=scoreMap(d);const values=exams.map(e=>map.get(scoreKey(s.id,c.id,e.id)));const complete=exams.length>0&&values.every(v=>v!==null&&v!==undefined);const total=values.reduce<number>((n,v)=>n+(v??0),0);const maximum=exams.reduce((n,e)=>n+e.maxMarks,0);const percentage=maximum?total/maximum*100:0;const grade=complete?gradeFor(percentage,d.settings.bands):{min:0,letter:'—',point:0};return {exams,values,complete,total,maximum,percentage,grade};}
export function semesterResult(d:AcademicData,s:Student,sem:number){const courses=d.courses.filter(c=>c.departmentId===s.departmentId&&c.semester===sem);const results=courses.map(c=>({course:c,...courseResult(d,s,c)}));const credits=results.filter(r=>r.complete).reduce((n,r)=>n+r.course.credits,0);const points=results.filter(r=>r.complete).reduce((n,r)=>n+r.course.credits*r.grade.point,0);return {results,credits,totalCredits:courses.reduce((n,c)=>n+c.credits,0),earned:results.filter(r=>r.complete&&r.grade.point>0).reduce((n,r)=>n+r.course.credits,0),gpa:credits?points/credits:0,complete:courses.length>0&&results.every(r=>r.complete),pending:results.filter(r=>!r.complete).length,failed:results.filter(r=>r.complete&&r.grade.point===0).length,published:d.published.includes(keyFor(s.session,s.departmentId,sem))};}
export function cumulative(d:AcademicData,s:Student,publishedOnly=true){const latest=new Map<string,{credits:number;point:number}>();for(const c of d.courses.filter(c=>c.departmentId===s.departmentId&&c.semester<=s.semester).sort((a,b)=>a.semester-b.semester)){if(publishedOnly&&!d.published.includes(keyFor(s.session,s.departmentId,c.semester)))continue;const r=courseResult(d,s,c);if(r.complete)latest.set(c.code.toUpperCase(),{credits:c.credits,point:r.grade.point});}let points=0,credits=0,earned=0;latest.forEach(r=>{points+=r.credits*r.point;credits+=r.credits;if(r.point>0)earned+=r.credits;});return {cgpa:credits?points/credits:0,credits,earned};}
export function cohortFor(d:AcademicData,session:string,departmentId:string,semester:number){return d.students.filter(s=>s.session===session&&s.departmentId===departmentId&&s.semester>=semester).sort((a,b)=>a.registration.localeCompare(b.registration,undefined,{numeric:true}));}
export function publicationCheck(d:AcademicData,session:string,departmentId:string,semester:number){const students=cohortFor(d,session,departmentId,semester);const courses=d.courses.filter(c=>c.departmentId===departmentId&&c.semester===semester);const exams=planFor(d,session,departmentId,semester);let pending=0;for(const s of students)for(const c of courses)for(const e of exams){const v=scoreMap(d).get(scoreKey(s.id,c.id,e.id));if(v===null||v===undefined)pending++;}return {students,courses,exams,pending,ready:students.length>0&&courses.length>0&&exams.length>0&&pending===0};}
export function studentData(d:AcademicData,studentId:string):AcademicData{const s=d.students.find(s=>s.id===studentId);if(!s)throw Error('Student account is not linked to a record.');const keys=d.published.filter(k=>k.startsWith(`${s.session}|${s.departmentId}|`));return {...d,students:[s],departments:d.departments.filter(x=>x.id===s.departmentId),courses:d.courses.filter(c=>c.departmentId===s.departmentId),scores:d.scores.filter(m=>m.studentId===s.id&&keys.includes(keyFor(s.session,s.departmentId,d.courses.find(c=>c.id===m.courseId)?.semester||0))),plans:d.plans.filter(p=>p.key.startsWith(`${s.session}|${s.departmentId}|`)),published:keys,activities:[]};}
