export const academicSchema=z.object({version:z.literal(2),departments:z.array(z.object({id,name:z.string().min(1).max(120),code:z.string().min(1).max(12)})).max(100),students:z.array(z.object({id,registration:z.string().min(1).max(40).regex(/^[a-zA-Z0-9_.-]+$/),roll:z.string().max(40),name:z.string().min(1).max(100),fatherName:z.string().max(100),motherName:z.string().max(100),email:z.string().max(150).refine(v=>!v||z.string().email().safeParse(v).success),dateOfBirth:z.string().max(20),departmentId:id,session,semester:z.number().int().min(1).max(8)})).max(2000),courses:z.array(z.object({id,code:z.string().min(1).max(30),name:z.string().min(1).max(150),departmentId:id,semester:z.number().int().min(1).max(8),credits:z.number().min(.5).max(10)})).max(1000),exams:z.array(z.object({id,name:z.string().min(1).max(80),maxMarks:z.number().min(1).max(1000)})).max(40),scores:z.array(z.object({studentId:id,courseId:id,examId:id,value:z.number().min(0).max(1000).nullable()})).max(100000),plans:z.array(z.object({key:z.string().max(200),examIds:z.array(id).min(1).max(40)})).max(1000),published:z.array(z.string().max(200)).max(1000),settings:z.object({institution:z.string().min(1).max(150),subtitle:z.string().max(120),address:z.string().max(200),examOffice:z.string().max(150),bands:z.array(z.object({min:z.number().min(0).max(100),letter:z.string().min(1).max(4),point:z.number().min(0).max(4)})).min(2).max(15),defaultExamIds:z.array(id).max(40)}),activities:z.array(z.object({id:z.string(),text:z.string().max(250),time:z.string()})).max(100)});
export function validateAcademic(d:AcademicData,previous?:AcademicData){
 const unique=(v:string[])=>new Set(v.map(x=>x.toLowerCase())).size===v.length;
 for(const [label,v] of [['department IDs',d.departments.map(x=>x.id)],['department names',d.departments.map(x=>x.name)],['department codes',d.departments.map(x=>x.code)],['student IDs',d.students.map(x=>x.id)],['registration numbers',d.students.map(x=>x.registration)],['course IDs',d.courses.map(x=>x.id)],['course codes',d.courses.map(x=>`${x.departmentId}|${x.semester}|${x.code}`)],['exam IDs',d.exams.map(x=>x.id)],['exam names',d.exams.map(x=>x.name)],['marks',d.scores.map(x=>scoreKey(x.studentId,x.courseId,x.examId))],['semester assessment plans',d.plans.map(x=>x.key)]] as [string,string[]][]){if(!unique(v))throw Error(`Duplicate ${label} are not allowed.`);}
 if(d.students.some(s=>s.registration.toLowerCase()==='admin'))throw Error('The registration number admin is reserved.');
 if(d.students.some(s=>!d.departments.some(x=>x.id===s.departmentId))||d.courses.some(c=>!d.departments.some(x=>x.id===c.departmentId)))throw Error('Choose an existing department.');
 for(const s of d.scores){const student=d.students.find(x=>x.id===s.studentId),course=d.courses.find(x=>x.id===s.courseId),exam=d.exams.find(x=>x.id===s.examId);if(!student||!course||!exam||student.departmentId!==course.departmentId||course.semester>student.semester)throw Error('Invalid student, course, or examination in marks.');if(s.value!==null&&(!Number.isFinite(s.value)||s.value<0||s.value>exam.maxMarks))throw Error(`${exam.name} marks must be between 0 and ${exam.maxMarks}.`);}
 for(const p of d.plans){const [ss,dep,sem]=p.key.split('|');if(!ss||!d.departments.some(x=>x.id===dep)||!Number.isInteger(Number(sem))||Number(sem)<1||Number(sem)>8||!unique(p.examIds)||p.examIds.some(x=>!d.exams.some(e=>e.id===x)))throw Error('Invalid semester assessment plan.');}
 if(!unique(d.settings.defaultExamIds)||d.settings.defaultExamIds.some(id=>!d.exams.some(e=>e.id===id)))throw Error('Invalid default examination plan.');
 const bands=[...d.settings.bands].sort((a,b)=>a.min-b.min);if(bands[0].min!==0||bands[0].point!==0||!unique(bands.map(b=>String(b.min)))||!unique(bands.map(b=>b.letter))||bands.some((b,i)=>i>0&&b.point<bands[i-1].point))throw Error('Grading bands must start at 0 marks / 0 points and increase with unique labels and thresholds.');
 if(previous){for(const key of previous.published.filter(k=>d.published.includes(k))){const [ss,dep,sem]=key.split('|');const n=Number(sem);if(JSON.stringify(previous.settings.bands)!==JSON.stringify(d.settings.bands))throw Error('Unpublish results before changing grade boundaries.');const oldPlan=planFor(previous,ss,dep,n),newPlan=planFor(d,ss,dep,n);if(oldPlan.map(e=>e.id+':'+e.maxMarks).join('|')!==newPlan.map(e=>e.id+':'+e.maxMarks).join('|'))throw Error('Unpublish results before changing published exam weights.');const oldCourses=previous.courses.filter(c=>c.departmentId===dep&&c.semester===n),newCourses=d.courses.filter(c=>c.departmentId===dep&&c.semester===n);if(oldCourses.map(c=>[c.id,c.code,c.credits].join(':')).join('|')!==newCourses.map(c=>[c.id,c.code,c.credits].join(':')).join('|'))throw Error('Unpublish results before changing published courses or credits.');const oldStudents=cohortFor(previous,ss,dep,n),newStudents=cohortFor(d,ss,dep,n);if(oldStudents.map(s=>s.id).join('|')!==newStudents.map(s=>s.id).join('|'))throw Error('Unpublish results before changing a published student cohort.');for(const s of oldStudents)for(const c of oldCourses)for(const e of oldPlan)if(scoreMap(previous).get(scoreKey(s.id,c.id,e.id))!==scoreMap(d).get(scoreKey(s.id,c.id,e.id)))throw Error('Published marks are locked. Unpublish this semester first.');}}
 for(const key of d.published){const [ss,dep,sem]=key.split('|');if(!publicationCheck(d,ss,dep,Number(sem)).ready)throw Error('Complete all marks for every student and exam before publishing.');}
}
